export const PLATFORM_LABELS: Partial<Record<PlatformId, string>> = {
  chatgpt: 'ChatGPT',
  claude: 'Claude',
  gemini: 'Gemini',
  deepseek: 'DeepSeek',
  grok: 'Grok',
  perplexity: 'Perplexity',
  meta: 'Meta AI',
  copilot: 'Copilot',
  mistral: 'Le Chat',
  kimi: 'Kimi',
  poe: 'Poe',
  duckduckgo: 'DuckDuckGo AI',
};

export function platformIconSvg(id: PlatformId, size = 18): string {
  const ic = PLATFORM_ICONS[id];
  if (!ic) return '';
  return `<svg viewBox="0 0 24 24" width=${size} height=${size} aria-hidden="true"><path d="${ic.path}" fill="${ic.color}"/></svg>`;
}
